#[doc(hidden)]
#[allow(dead_code, clippy::all)]
pub mod __prpr_runtime {
extern crate alloc;

// Runtime support for parsers generated by prpr.
//
// This file only refers to `core` and `alloc` and never to `crate::`, so that the code
// generator can inline it into a generated file as a module.

use alloc::borrow::Cow;
use alloc::collections::{BTreeMap, BTreeSet};
use alloc::string::ToString;
use core::fmt;
use core::range::Range;

#[doc(hidden)]
pub use alloc::vec::Vec;

/// The `(major, minor)` version of this runtime.
#[doc(hidden)]
pub const VERSION: (u32, u32) = (0, 1);

/// Fails at compile time when generated code was made for an incompatible runtime.
#[doc(hidden)]
pub const fn require_version(major: u32, minor: u32) {
    let ok = if major == 0 {
        VERSION.0 == 0 && VERSION.1 == minor
    } else {
        VERSION.0 == major && VERSION.1 >= minor
    };
    if !ok {
        panic!("this parser was generated for an incompatible version of prpr-runtime");
    }
}

/// A failed match. What was expected is recorded in [`Cx`].
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Fail;

/// The result of a rule: its value and the position after it.
pub type PResult<T> = Result<(T, usize), Fail>;

/// The kinds of input a parser runs on: `str` and `[u8]`.
pub trait Input {
    /// The input as bytes; positions in the input are byte offsets.
    fn as_bytes(&self) -> &[u8];

    /// What is found at a byte position, for error messages.
    fn found_at(&self, pos: usize) -> Found;
}

impl Input for str {
    #[inline]
    fn as_bytes(&self) -> &[u8] {
        str::as_bytes(self)
    }

    fn found_at(&self, pos: usize) -> Found {
        match self.get(pos..).and_then(|s| s.chars().next()) {
            Some(c) => Found::Char(c),
            None => Found::Eof,
        }
    }
}

impl Input for [u8] {
    #[inline]
    fn as_bytes(&self) -> &[u8] {
        self
    }

    fn found_at(&self, pos: usize) -> Found {
        match self.get(pos) {
            Some(b) => Found::Byte(*b),
            None => Found::Eof,
        }
    }
}

/// The span from `start` to `end`, as a range of byte offsets of the input. If `start > end`,
/// it is the empty span at `end`.
#[inline]
#[doc(hidden)]
pub const fn span(start: usize, end: usize) -> Range<usize> {
    Range {
        start: if start <= end { start } else { end },
        end,
    }
}

/// Something the parser expected at the error position.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[non_exhaustive]
pub enum Expected {
    /// A literal string.
    Literal(&'static str),
    /// A literal byte string.
    Bytes(&'static [u8]),
    /// A character class, as written in the grammar.
    Class(&'static str),
    /// The label of a rule.
    Label(&'static str),
    /// Any character or byte.
    Any,
    /// The end of the input.
    Eof,
    /// A delimiter after a token, e.g. not `x` right after the number in `123x`.
    Delimiter,
    /// A message from a semantic predicate.
    Message(Cow<'static, str>),
}

impl fmt::Display for Expected {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Expected::Literal(s) => {
                f.write_str("`")?;
                s.chars().try_for_each(|c| write_escaped(f, c))?;
                f.write_str("`")
            }
            Expected::Bytes(bs) => {
                f.write_str("`b\"")?;
                for b in bs.iter() {
                    write!(f, "{}", b.escape_ascii())?;
                }
                f.write_str("\"`")
            }
            Expected::Class(s) => write!(f, "`{s}`"),
            Expected::Label(s) => f.write_str(s),
            Expected::Any => f.write_str("any character"),
            Expected::Eof => f.write_str("end of input"),
            Expected::Delimiter => f.write_str("delimiter"),
            Expected::Message(s) => f.write_str(s),
        }
    }
}

// Escapes a character for a message, where it is quoted with backticks.
fn write_escaped(f: &mut fmt::Formatter<'_>, c: char) -> fmt::Result {
    match c {
        '"' | '\'' => write!(f, "{c}"),
        c => write!(f, "{}", c.escape_debug()),
    }
}

/// What was found at the error position.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Found {
    /// A character of text input.
    Char(char),
    /// A byte of binary input.
    Byte(u8),
    /// The end of the input.
    Eof,
}

impl Found {
    /// The length of what was found, in bytes.
    pub const fn byte_len(&self) -> usize {
        match self {
            Found::Char(c) => c.len_utf8(),
            Found::Byte(_) => 1,
            Found::Eof => 0,
        }
    }
}

impl fmt::Display for Found {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Found::Char(c) => {
                f.write_str("`")?;
                write_escaped(f, *c)?;
                f.write_str("`")
            }
            Found::Byte(b) => write!(f, "`b'{}'`", b.escape_ascii()),
            Found::Eof => f.write_str("end of input"),
        }
    }
}

/// The state shared by all rules during one parse: the input and the farthest failure.
pub struct Cx<'i, I: ?Sized> {
    input: &'i I,
    bytes: &'i [u8],
    // The farthest position of a failure.
    err_pos: usize,
    // What was expected, with positions in non-decreasing order. Entries before `err_pos` are
    // only kept while a mark is active, so that the state can be rolled back to the mark.
    expected: Vec<(usize, Expected)>,
    marks: u32,
    quiet: u32,
    label: Option<(usize, &'static str)>,
    // Whether failures are recorded at all.
    tracking: bool,
}

/// The label in effect before [`Cx::push_label`].
#[derive(Clone, Copy, Debug)]
#[doc(hidden)]
pub struct SavedLabel(Option<(usize, &'static str)>);

/// The error state at [`Cx::mark`].
#[derive(Clone, Copy, Debug)]
pub struct ErrorMark {
    err_pos: usize,
    len: usize,
}

impl<'i, I: Input + ?Sized> Cx<'i, I> {
    /// A context that records what is expected where parsing fails.
    pub fn new(input: &'i I) -> Self {
        Self {
            input,
            bytes: input.as_bytes(),
            err_pos: 0,
            expected: Vec::new(),
            marks: 0,
            quiet: 0,
            label: None,
            tracking: true,
        }
    }

    /// A context that does not record failures, which makes parsing faster but leaves
    /// [`Cx::error`] meaningless.
    pub fn without_errors(input: &'i I) -> Self {
        Self {
            tracking: false,
            ..Self::new(input)
        }
    }

    /// The input.
    #[inline]
    pub fn input(&self) -> &'i I {
        self.input
    }

    /// The input as bytes.
    #[inline]
    pub fn bytes(&self) -> &'i [u8] {
        self.bytes
    }

    /// The length of the input in bytes.
    #[inline]
    pub fn len(&self) -> usize {
        self.bytes.len()
    }

    /// Whether the input is empty.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.bytes.is_empty()
    }

    /// Matches a literal at `pos`.
    #[inline]
    pub fn lit(&mut self, pos: usize, lit: &'static str) -> Result<usize, Fail> {
        match self.bytes.get(pos..) {
            Some(rest) if rest.starts_with(lit.as_bytes()) => Ok(pos + lit.len()),
            _ => Err(self.fail(pos, Expected::Literal(lit))),
        }
    }

    /// Matches a literal byte string at `pos`.
    #[inline]
    pub fn lit_bytes(&mut self, pos: usize, lit: &'static [u8]) -> Result<usize, Fail> {
        match self.bytes.get(pos..) {
            Some(rest) if rest.starts_with(lit) => Ok(pos + lit.len()),
            _ => Err(self.fail(pos, Expected::Bytes(lit))),
        }
    }

    /// Records that `expected` was expected at `pos`.
    #[inline]
    pub fn expect(&mut self, pos: usize, expected: Expected) {
        if self.tracking && pos >= self.err_pos && self.quiet == 0 {
            self.record(pos, Some(expected));
        }
    }

    /// Records a failure at `pos` and returns [`Fail`].
    #[inline]
    pub fn fail(&mut self, pos: usize, expected: Expected) -> Fail {
        self.expect(pos, expected);
        Fail
    }

    /// Records a failure at `pos` without saying what was expected, so that the error is
    /// reported as "unexpected ...", unless a label is in effect at `pos`.
    #[inline]
    pub fn fail_unexpected(&mut self, pos: usize) -> Fail {
        if self.tracking && pos >= self.err_pos && self.quiet == 0 {
            self.record(pos, None);
        }
        Fail
    }

    #[cold]
    #[inline(never)]
    fn record(&mut self, pos: usize, expected: Option<Expected>) {
        if pos > self.err_pos {
            self.err_pos = pos;
            if self.marks == 0 {
                self.expected.clear();
            }
        }
        let expected = match (self.label, expected) {
            (Some((label_pos, label)), _) if label_pos == pos => Expected::Label(label),
            (_, Some(expected)) => expected,
            (_, None) => return,
        };
        let recorded = self.expected.iter().rev().take_while(|(p, _)| *p == pos);
        if !recorded.into_iter().any(|(_, e)| *e == expected) {
            self.expected.push((pos, expected));
        }
    }

    /// Marks the error state, to roll back to it with [`Cx::rollback`] or to keep what was
    /// recorded since with [`Cx::commit`].
    #[inline]
    pub fn mark(&mut self) -> ErrorMark {
        self.marks += 1;
        ErrorMark {
            err_pos: self.err_pos,
            len: self.expected.len(),
        }
    }

    /// Forgets the failures recorded since `mark`.
    #[inline]
    pub fn rollback(&mut self, mark: ErrorMark) {
        self.marks -= 1;
        self.expected.truncate(mark.len);
        self.err_pos = mark.err_pos;
    }

    /// Keeps the failures recorded since `mark`.
    #[inline]
    pub fn commit(&mut self, _mark: ErrorMark) {
        self.marks -= 1;
    }

    /// Records the failure of a semantic predicate about the input from `pos`, which was
    /// matched since `mark`.
    ///
    /// With a message, the input matched but is invalid as a whole, so what was expected within
    /// it is forgotten and the message is reported at `pos`. Without one, the predicate is just
    /// a filter.
    #[cold]
    #[doc(hidden)]
    pub fn fail_predicate(
        &mut self,
        mark: ErrorMark,
        pos: usize,
        message: Option<Cow<'static, str>>,
    ) -> Fail {
        match message {
            Some(message) => {
                self.rollback(mark);
                self.fail(pos, Expected::Message(message))
            }
            None => {
                self.commit(mark);
                self.fail_unexpected(pos)
            }
        }
    }

    /// Stops recording failures until the matching [`Cx::pop_quiet`].
    #[inline]
    #[doc(hidden)]
    pub fn push_quiet(&mut self) {
        self.quiet += 1;
    }

    #[inline]
    #[doc(hidden)]
    pub fn pop_quiet(&mut self) {
        self.quiet -= 1;
    }

    /// Reports `label` instead of whatever is expected at `pos`, until the matching
    /// [`Cx::pop_label`]. An enclosing label at the same position takes precedence.
    #[inline]
    #[doc(hidden)]
    pub fn push_label(&mut self, pos: usize, label: &'static str) -> SavedLabel {
        let saved = SavedLabel(self.label);
        if !matches!(self.label, Some((p, _)) if p == pos) {
            self.label = Some((pos, label));
        }
        saved
    }

    #[inline]
    #[doc(hidden)]
    pub fn pop_label(&mut self, saved: SavedLabel) {
        self.label = saved.0;
    }

    /// The error for the farthest failure recorded so far.
    pub fn error(&self) -> ParseError {
        let mut expected: Vec<Expected> = self
            .expected
            .iter()
            .filter(|(p, _)| *p == self.err_pos)
            .map(|(_, e)| e.clone())
            .collect();
        expected.sort();
        expected.dedup();
        ParseError::new(self.err_pos, expected, self.input.found_at(self.err_pos))
    }
}

impl<'i> Cx<'i, str> {
    /// The character at `pos` and the position after it.
    #[inline]
    pub fn peek_char(&self, pos: usize) -> Option<(char, usize)> {
        let b = *self.bytes.get(pos)?;
        if b < 0x80 {
            return Some((b as char, pos + 1));
        }
        let c = self.input.get(pos..)?.chars().next()?;
        Some((c, pos + c.len_utf8()))
    }

    /// The position where the character that ends at `pos` starts.
    #[inline]
    pub fn char_start_before(&self, pos: usize) -> Option<usize> {
        let mut start = pos.checked_sub(1)?;
        while start > 0 && (self.bytes[start] & 0xc0) == 0x80 {
            start -= 1;
        }
        Some(start)
    }

    /// The input between two positions. If `start > end`, the slice is empty.
    #[inline]
    pub fn slice(&self, start: usize, end: usize) -> &'i str {
        &self.input[start.min(end)..end]
    }
}

impl<'i> Cx<'i, [u8]> {
    /// The byte at `pos` and the position after it.
    #[inline]
    pub fn peek_byte(&self, pos: usize) -> Option<(u8, usize)> {
        Some((*self.bytes.get(pos)?, pos + 1))
    }

    /// The position where the byte that ends at `pos` starts.
    #[inline]
    pub fn char_start_before(&self, pos: usize) -> Option<usize> {
        pos.checked_sub(1)
    }

    /// The input between two positions. If `start > end`, the slice is empty.
    #[inline]
    pub fn slice(&self, start: usize, end: usize) -> &'i [u8] {
        &self.input[start.min(end)..end]
    }
}

/// The result of a semantic predicate `&{ ... }`.
#[doc(hidden)]
pub trait Predicate {
    type Output;

    /// `Err(Some(message))` reports the message as expected; `Err(None)` reports nothing.
    fn into_outcome(self) -> Result<Self::Output, Option<Cow<'static, str>>>;
}

impl Predicate for bool {
    type Output = ();

    #[inline]
    fn into_outcome(self) -> Result<(), Option<Cow<'static, str>>> {
        if self { Ok(()) } else { Err(None) }
    }
}

impl<T> Predicate for Option<T> {
    type Output = T;

    #[inline]
    fn into_outcome(self) -> Result<T, Option<Cow<'static, str>>> {
        self.ok_or(None)
    }
}

impl<T, E: fmt::Display> Predicate for Result<T, E> {
    type Output = T;

    #[inline]
    fn into_outcome(self) -> Result<T, Option<Cow<'static, str>>> {
        self.map_err(|e| Some(Cow::Owned(e.to_string())))
    }
}

/// A cache of the last result of the implicit whitespace rule.
#[derive(Clone, Copy, Debug)]
#[doc(hidden)]
pub struct SkipCache {
    pos: usize,
    end: usize,
}

impl Default for SkipCache {
    fn default() -> Self {
        Self {
            pos: usize::MAX,
            end: 0,
        }
    }
}

impl SkipCache {
    #[inline]
    pub fn get(&self, pos: usize) -> Option<usize> {
        if self.pos == pos {
            Some(self.end)
        } else {
            None
        }
    }

    #[inline]
    pub fn set(&mut self, pos: usize, end: usize) {
        self.pos = pos;
        self.end = end;
    }
}

/// The results of a rule with `#[memo]`, by position.
///
/// A cached result is handed out every time the rule is invoked at the same position, so the
/// value is cloned with the function that `get` and `insert` take.
#[doc(hidden)]
pub struct MemoTable<T> {
    // Open addressing with linear probing; the capacity is zero or a power of two.
    slots: Vec<Option<(usize, PResult<T>)>>,
    len: usize,
}

impl<T> Default for MemoTable<T> {
    fn default() -> Self {
        Self {
            slots: Vec::new(),
            len: 0,
        }
    }
}

impl<T> MemoTable<T> {
    #[inline]
    fn index(&self, pos: usize) -> usize {
        // Fibonacci hashing.
        let hash = (pos as u64).wrapping_mul(0x9e37_79b9_7f4a_7c15);
        (hash >> (64 - self.slots.len().trailing_zeros())) as usize
    }

    /// The result of the rule at `pos`, if it is known.
    #[inline]
    pub fn get(&self, pos: usize, clone: impl Fn(&T) -> T) -> Option<PResult<T>> {
        if self.slots.is_empty() {
            return None;
        }
        let mask = self.slots.len() - 1;
        let mut i = self.index(pos);
        loop {
            match &self.slots[i] {
                Some((p, result)) if *p == pos => {
                    return Some(
                        result
                            .as_ref()
                            .map(|(v, end)| (clone(v), *end))
                            .map_err(|f| *f),
                    );
                }
                Some(_) => i = (i + 1) & mask,
                None => return None,
            }
        }
    }

    /// Records the result of the rule at `pos`.
    pub fn insert(&mut self, pos: usize, result: &PResult<T>, clone: impl Fn(&T) -> T) {
        if (self.len + 1) * 2 > self.slots.len() {
            self.grow();
        }
        let result = result
            .as_ref()
            .map(|(v, end)| (clone(v), *end))
            .map_err(|f| *f);
        let mask = self.slots.len() - 1;
        let mut i = self.index(pos);
        while let Some((p, _)) = &self.slots[i] {
            if *p == pos {
                self.slots[i] = Some((pos, result));
                return;
            }
            i = (i + 1) & mask;
        }
        self.slots[i] = Some((pos, result));
        self.len += 1;
    }

    fn grow(&mut self) {
        let capacity = (self.slots.len() * 2).max(16);
        let old = core::mem::replace(&mut self.slots, (0..capacity).map(|_| None).collect());
        let mask = capacity - 1;
        for (pos, result) in old.into_iter().flatten() {
            let mut i = self.index(pos);
            while self.slots[i].is_some() {
                i = (i + 1) & mask;
            }
            self.slots[i] = Some((pos, result));
        }
    }
}

/// Runs `rule` from the start of `input` and requires the whole input to be consumed.
/// `trailing` skips what may follow the rule (e.g. whitespace).
///
/// The first attempt does not record failures, which is cheaper. Only when it fails is the
/// input parsed again to find out what was expected, so actions may run twice for invalid
/// input.
pub fn parse_full<'i, I, M, T>(
    input: &'i I,
    rule: impl Fn(&mut Cx<'i, I>, &mut M, usize) -> PResult<T>,
    trailing: impl Fn(&mut Cx<'i, I>, &mut M, usize) -> usize,
) -> Result<T, ParseError>
where
    I: Input + ?Sized,
    M: Default,
{
    let run = |cx: &mut Cx<'i, I>| {
        let mut memo = M::default();
        let (value, pos) = rule(cx, &mut memo, 0).ok()?;
        let pos = trailing(cx, &mut memo, pos);
        if pos == cx.len() {
            return Some(value);
        }
        cx.expect(pos, Expected::Eof);
        None
    };
    if let Some(value) = run(&mut Cx::without_errors(input)) {
        return Ok(value);
    }
    let mut cx = Cx::new(input);
    run(&mut cx).ok_or_else(|| cx.error())
}

/// Skips nothing; the `trailing` argument of [`parse_full`] for rules without implicit whitespace.
pub fn no_skip<I: ?Sized, M>(_cx: &mut Cx<'_, I>, _memo: &mut M, pos: usize) -> usize {
    pos
}

/// Runs `rule` from the start of `input` and returns its value and the position after it.
/// Like [`parse_full`], it parses twice when it fails.
pub fn parse_prefix<'i, I, M, T>(
    input: &'i I,
    rule: impl Fn(&mut Cx<'i, I>, &mut M, usize) -> PResult<T>,
) -> Result<(T, usize), ParseError>
where
    I: Input + ?Sized,
    M: Default,
{
    if let Ok(result) = rule(&mut Cx::without_errors(input), &mut M::default(), 0) {
        return Ok(result);
    }
    let mut cx = Cx::new(input);
    rule(&mut cx, &mut M::default(), 0).map_err(|_| cx.error())
}

/// Runs `rule` from the start of `input`, like [`parse_prefix`], and returns how often the rules of
/// its grammar, which must have `#![profile]`, were called. The input is parsed once, recording
/// failures.
pub fn profile<'i, I, M, T>(
    input: &'i I,
    rule: impl Fn(&mut Cx<'i, I>, &mut M, usize) -> PResult<T>,
) -> (Result<(T, usize), ParseError>, Profile)
where
    I: Input + ?Sized,
    M: Default + Profiled,
{
    let mut cx = Cx::new(input);
    let mut memo = M::default();
    let result = rule(&mut cx, &mut memo, 0).map_err(|_| cx.error());
    (result, core::mem::take(memo.profile()))
}

/// The `Memo` of a grammar with `#![profile]`, whose rules count their calls in it.
#[diagnostic::on_unimplemented(
    message = "the grammar of `{Self}` does not count the calls of its rules",
    label = "a rule of a grammar without `#![profile]`",
    note = "add `#![profile]` to the grammar"
)]
pub trait Profiled {
    /// The counts so far.
    fn profile(&mut self) -> &mut Profile;
}

/// How often the rules of a grammar were called, as [`profile`] returns it.
///
/// Its `Display` writes a table of the rules, those that were parsed again at the same position
/// most often first: they are the ones that memoization would speed up.
#[derive(Clone, Debug, Default)]
pub struct Profile {
    rules: Vec<RuleProfile>,
    index: BTreeMap<&'static str, usize>,
    // The rules (by index) and positions of the calls so far.
    seen: BTreeSet<(usize, usize)>,
}

/// The calls of one rule.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RuleProfile {
    /// The name of the rule.
    pub rule: &'static str,
    /// How many times the rule was invoked.
    pub calls: u64,
    /// How many of the calls were at a position where the rule had already been invoked.
    pub repeated: u64,
    /// How many of the repeated calls returned a memoized result.
    pub memo_hits: u64,
}

impl RuleProfile {
    /// How many times the rule was parsed again at the same position, which memoization would
    /// avoid.
    pub fn reparsed(&self) -> u64 {
        self.repeated - self.memo_hits
    }
}

impl Profile {
    /// The rules that were invoked, in the order of their first calls.
    pub fn rules(&self) -> &[RuleProfile] {
        &self.rules
    }

    fn entry(&mut self, rule: &'static str) -> usize {
        let next = self.rules.len();
        let i = *self.index.entry(rule).or_insert(next);
        if i == next {
            self.rules.push(RuleProfile {
                rule,
                calls: 0,
                repeated: 0,
                memo_hits: 0,
            });
        }
        i
    }

    /// Counts a call of `rule` at `pos`.
    #[doc(hidden)]
    pub fn record_call(&mut self, rule: &'static str, pos: usize) {
        let i = self.entry(rule);
        self.rules[i].calls += 1;
        if !self.seen.insert((i, pos)) {
            self.rules[i].repeated += 1;
        }
    }

    /// Counts a call of `rule` that returned a memoized result.
    #[doc(hidden)]
    pub fn record_memo_hit(&mut self, rule: &'static str) {
        let i = self.entry(rule);
        self.rules[i].memo_hits += 1;
    }
}

impl fmt::Display for Profile {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut rules: Vec<&RuleProfile> = self.rules.iter().collect();
        rules.sort_by_key(|r| {
            (
                core::cmp::Reverse(r.reparsed()),
                core::cmp::Reverse(r.calls),
            )
        });
        let width = rules.iter().map(|r| r.rule.len()).max().unwrap_or(0).max(4);
        write!(
            f,
            "{:width$}  {:>10}  {:>10}  {:>10}  {:>10}",
            "rule", "calls", "repeated", "memo hits", "reparsed"
        )?;
        for r in rules {
            write!(
                f,
                "\n{:width$}  {:>10}  {:>10}  {:>10}  {:>10}",
                r.rule,
                r.calls,
                r.repeated,
                r.memo_hits,
                r.reparsed()
            )?;
        }
        Ok(())
    }
}

/// A parse error: what was expected at the farthest position the parser reached.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ParseError {
    offset: usize,
    expected: Vec<Expected>,
    found: Found,
}

impl ParseError {
    /// An error at byte offset `offset`, where `found` was found instead of what was `expected`.
    pub fn new(offset: usize, expected: Vec<Expected>, found: Found) -> Self {
        Self {
            offset,
            expected,
            found,
        }
    }

    /// The byte offset of the error.
    pub fn offset(&self) -> usize {
        self.offset
    }

    /// The span of what was found at the error position (empty at the end of the input).
    pub fn span(&self) -> Range<usize> {
        span(self.offset, self.offset + self.found.byte_len())
    }

    /// What was expected, sorted and without duplicates.
    pub fn expected(&self) -> &[Expected] {
        &self.expected
    }

    /// What was found at the error position.
    pub fn found(&self) -> Found {
        self.found
    }

    /// The line and column of the error in `src`, which must be the parsed input.
    pub fn line_col(&self, src: &str) -> LineCol {
        line_col(src, self.offset)
    }

    /// Renders the error with the offending line of `src`, in the style of rustc.
    /// `origin` names the source, e.g. a file name.
    pub fn render<'a>(&'a self, src: &'a str, origin: &'a str) -> Snippet<'a> {
        Snippet {
            level: "error",
            message: self,
            src,
            origin,
            span: self.span(),
        }
    }
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self.expected.as_slice() {
            [] => return write!(f, "unexpected {}", self.found),
            [e] => write!(f, "expected {e}")?,
            [a, b] => write!(f, "expected one of {a} or {b}")?,
            [init @ .., last] => {
                f.write_str("expected one of ")?;
                for e in init {
                    write!(f, "{e}, ")?;
                }
                write!(f, "or {last}")?;
            }
        }
        write!(f, ", found {}", self.found)
    }
}

impl core::error::Error for ParseError {}

/// A one-based line and column. Columns count characters.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct LineCol {
    /// The line, from 1.
    pub line: usize,
    /// The column in characters, from 1.
    pub column: usize,
}

/// The line and column of a byte offset in `src`.
pub fn line_col(src: &str, offset: usize) -> LineCol {
    let offset = floor_char_boundary(src, offset);
    let before = &src[..offset];
    let line_start = before.rfind('\n').map_or(0, |i| i + 1);
    LineCol {
        line: before.matches('\n').count() + 1,
        column: before[line_start..].chars().count() + 1,
    }
}

fn floor_char_boundary(src: &str, offset: usize) -> usize {
    let mut offset = offset.min(src.len());
    while !src.is_char_boundary(offset) {
        offset -= 1;
    }
    offset
}

/// A message pointing at a span of a source text, rendered in the style of rustc:
///
/// ```text
/// error: expected `bar`, found `b`
///  --> input.txt:1:5
///   |
/// 1 | foo baz
///   |     ^
/// ```
pub struct Snippet<'a> {
    /// The word before the message, e.g. `error` or `warning`.
    pub level: &'a str,
    /// The message.
    pub message: &'a dyn fmt::Display,
    /// The source text that `span` is in.
    pub src: &'a str,
    /// The name of the source, e.g. a file name.
    pub origin: &'a str,
    /// The byte range of `src` to point at. Only its first line is shown.
    pub span: Range<usize>,
}

impl fmt::Display for Snippet<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let start = floor_char_boundary(self.src, self.span.start);
        let end = floor_char_boundary(self.src, self.span.end.max(start));
        let LineCol { line, column } = line_col(self.src, start);
        let line_start = self.src[..start].rfind('\n').map_or(0, |i| i + 1);
        let line_end = self.src[start..]
            .find('\n')
            .map_or(self.src.len(), |i| start + i);
        let text = self.src[line_start..line_end].trim_end_matches('\r');

        let indent = " ".repeat(line.to_string().len());
        writeln!(f, "{}: {}", self.level, self.message)?;
        writeln!(f, "{indent}--> {}:{line}:{column}", self.origin)?;
        writeln!(f, "{indent} |")?;
        writeln!(f, "{line} | {text}")?;
        write!(f, "{indent} | ")?;
        for c in self.src[line_start..start].chars() {
            f.write_str(if c == '\t' { "\t" } else { " " })?;
        }
        let marked = self.src[start..end.min(line_end)].chars().count().max(1);
        for _ in 0..marked {
            f.write_str("^")?;
        }
        Ok(())
    }
}
}
